import ctypes

ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.c_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(self._wrapper)

    def _wrapper(self, x):
        return self.func(x)

class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = gsl.gsl_integration_workspace_alloc(size)

    def __del__(self):
        if hasattr(self, 'workspace'):
            gsl.gsl_integration_workspace_free(self.workspace)

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    try:
        gsl_function = GSLFunction(func)
        workspace = CQuadWorkspace(workspace_size)
        result = ctypes.c_double()
        abserr = ctypes.c_double()
        gsl.gsl_integration_qags(gsl_function.c_func, a, b, epsabs, epsrel, workspace_size, workspace.workspace, ctypes.byref(result), ctypes.byref(abserr))
        return result.value, abserr.value, workspace_size
    except Exception as e:
        return str(e)

