def prime_factors(num):
    factors = []
    divisor = 2
    while num >= divisor:
        if num % divisor == 0:
            factors.append(divisor)
            num //= divisor
        else:
            divisor += 1
    return factors

def fft_factorize(n):
    factors = prime_factors(n)
    return factors, len(factors)

