import numpy as np
import ctypes
from ctypes import c_double, POINTER, byref

class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

    @staticmethod
def numpy_to_gsl_matrix(np_array):
        rows, cols = np_array.shape
        gsl_matrix = GSLMatrix(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl_matrix.matrix.data[i * cols + j] = np_array[i, j]
        return gsl_matrix

    @staticmethod
def gsl_matrix_to_numpy(gsl_matrix):
        rows, cols = gsl_matrix.matrix.size1, gsl_matrix.matrix.size2
        np_array = np.zeros((rows, cols), dtype=np.double)
        for i in range(rows):
            for j in range(cols):
                np_array[i, j] = gsl_matrix.matrix.data[i * cols + j]
        return np_array

def compute_covariance(jacobian, epsrel):
    rows, cols = jacobian.shape
    if rows != cols:
        raise ValueError('Jacobian matrix must be square')
    covar = GSLMatrix(rows, rows)
    gsl.gsl_multifit_covar(byref(gsl_matrix_to_numpy(numpy_to_gsl_matrix(jacobian))), epsrel, byref(covar.matrix))
    return gsl_matrix_to_numpy(covar)

# Test cases
def test_compute_covariance():
    jacobian = np.array([[1, 2], [3, 4]], dtype=np.double)
    epsrel = 1e-6
    expected_output = np.array([[8, 10], [10, 13]], dtype=np.double)
    assert np.allclose(compute_covariance(jacobian, epsrel), expected_output, atol=epsrel)

