# Define GSLVector class
class GSLVector:
    def __init__(self, size):
        self.size = size
        self.vector = gsl.gsl_vector_alloc(size)

    def __del__(self):
        gsl.gsl_vector_free(self.vector)

    def set_values(self, values):
        for i, value in enumerate(values):
            gsl.gsl_vector_set(self.vector, i, value)

    def get_values(self):
        result = [0] * self.size
        for i in range(self.size):
            result[i] = gsl.gsl_vector_get(self.vector, i)
        return result

