# Define the function signature for gsl_poly_solve_quadratic
def compute_quadratic_roots(a, b, c):
    # Define the result array for roots
    roots = (ctypes.c_double * 2)()
    # Call the C function
    status = gsl.gsl_poly_solve_quadratic(a, b, c, roots[0], roots[1])
    # Check the status
    if status == 0:
        # Real and distinct roots
        return (roots[0].value, roots[1].value)
    elif status == -1:
        # Real and equal roots
        return (roots[0].value, roots[0].value)
    else:
        # Complex roots
        return None

