class GSLVector:
    def __init__(self, size):
        self.size = size
        self.vector = gsl.gsl_vector_alloc(self.size)
        if self.vector == None:
            raise Exception("Failed to allocate GSL vector")
        gslcblas.dset_zero(self.vector)

    def get_data(self):
        data = [0] * self.size
        for i in range(self.size):
            data[i] = gsl.gsl_vector_get(self.vector, i)
        return data

    def __del__(self):
        gsl.gsl_vector_free(self.vector)

def initialize_gsl_vector(size):
    return GSLVector(size).get_data()

