import numpy as np
def qr_decomposition(U, D, Y, T):
    # Load necessary libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define data types for GSL matrices and vectors
    gsl.gsl_matrix_double_p = ctypes.POINTER(gsl.gsl_matrix_double)
    gsl.gsl_vector_double_p = ctypes.POINTER(gsl.gsl_vector_double)

    # Convert numpy arrays to GSL matrices and vectors
    def numpy_to_gsl_matrix(matrix):
        m, n = matrix.shape
        gsl_mat = gsl.gsl_matrix_double(m, n)
        for i in range(m):
            for j in range(n):
                gsl_mat.data[i * n + j] = matrix[i, j]
        return gsl_mat

    def numpy_to_gsl_vector(vector):
        size = vector.size
        gsl_vec = gsl.gsl_vector_double(size)
        for i in range(size):
            gsl_vec.data[i] = vector[i]
        return gsl_vec

    # Call the QR decomposition function
    U_gsl = numpy_to_gsl_matrix(U)
    D_gsl = numpy_to_gsl_vector(D)
    Y_gsl = numpy_to_gsl_matrix(Y)
    T_gsl = numpy_to_gsl_matrix(T)

    gsl.qr_ud_decomp(U_gsl, D_gsl, Y_gsl, T_gsl)

    # Convert back to numpy arrays
    for i in range(U.shape[0]):
        for j in range(U.shape[1]):
            U[i, j] = U_gsl.data[i * U.shape[1] + j]
    for i in range(D.shape[0]):
        D[i] = D_gsl.data[i]
    for i in range(Y.shape[0]):
        for j in range(Y.shape[1]):
            Y[i, j] = Y_gsl.data[i * Y.shape[1] + j]
    for i in range(T.shape[0]):
        for j in range(T.shape[1]):
            T[i, j] = T_gsl.data[i * T.shape[1] + j]

    return Y, T

