import ctypes

ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

GSLMatrix = ctypes.c_void_p

def list_to_gsl_matrix(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    data_type = gsl.gsl_complex_double
    data_ptr = (data_type * (rows * cols))()
    for i in range(rows):
        for j in range(cols):
            data_ptr[i * cols + j] = data_type(real=matrix[i][j].real, imag=matrix[i][j].imag)
    matrix_ptr = gsl.gsl_matrix_calloc(rows, cols)
    gsl.gsl_matrix_set_data(matrix_ptr, data_ptr)
    return matrix_ptr

def add_matrices(matrix_a, matrix_b):
    rows = len(matrix_a)
    cols = len(matrix_a[0])
    result_matrix = gsl_matrix_calloc(rows, cols)
    gsl.gsl_matrix_add(result_matrix, matrix_a, matrix_b)
    return result_matrix

