            for j in range(cols):
                real = matrix[i][j].real
                imag = matrix[i][j].imag
                gsl.gsl_matrix_complex_set(gsl_matrix, i, j, real, imag)
        return gsl_matrix

    def __del__(self):
        gsl.gsl_matrix_complex_free(self.matrix)

