def add_matrices(matrix_a, matrix_b):
    if matrix_a.rows != matrix_b.rows or matrix_a.cols != matrix_b.cols:
        raise ValueError("Matrices must have the same dimensions")
    result_data = [[complex(0, 0) for _ in range(matrix_a.cols)] for _ in range(matrix_a.rows)]
    for i in range(matrix_a.rows):
        for j in range(matrix_a.cols):
            result_data[i][j] = matrix_a.data[i][j] + matrix_b.data[i][j]
    return GSLMatrix(result_data)

