# Define the matrix class
class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])
        self.matrix_ptr = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(self.matrix_ptr, i, j, data[i][j])

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix_ptr)

    def is_positive_definite(self):
        result = gsl.gsl_linalg_cholesky_decomp(self.matrix_ptr)
        if result != 0:
            raise ValueError("Matrix is not positive definite")

    def cholesky_decomp(self):
        self.is_positive_definite()
        L = [[0] * self.cols for _ in range(self.rows)]
        for i in range(self.rows):
            for j in range(i + 1):
                sum_k = sum(L[i][k] * L[j][k] for k in range(j))
                if i == j:
                    L[i][j] = (self.data[i][i] - sum_k) ** 0.5
                else:
                    L[i][j] = (self.data[i][j] - sum_k) / L[j][j]
        return L

