# Define gsl_function structure
class gsl_function(ctypes.Structure):
    _fields_ = [(\"function\", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))), (\"params\", ctypes.POINTER(ctypes.c_void_p))]

# Function wrapper for GSL integration
def func_wrapper(x, params):
    py_func = ctypes.cast(params, ctypes.POINTER(gsl_function)).contents.function
    return py_func(x, params)

# Compute integral using Romberg method
def compute_integral(py_func, a, b, epsabs, epsrel, n):
    # Allocate workspace
    workspace = gsl.gsl_integration_romberg_alloc(n)
    if not workspace:
        raise MemoryError('Failed to allocate workspace')

    # Create gsl_function instance
    func = gsl_function()
    func.function = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))(func_wrapper)
    func.params = ctypes.byref(ctypes.c_void_p.from_address(id(py_func)))

    # Perform integration
    result = ctypes.c_double(0)
    abserr = ctypes.c_double(0)
    status = gsl.gsl_integration_romberg(workspace, func, a, b, epsabs, epsrel, ctypes.byref(result), ctypes.byref(abserr))

    # Free workspace
    gsl.gsl_integration_romberg_free(workspace)

    if status != 0:
        raise RuntimeError(f'Integration failed with status {status}')

    return result.value, int(workspace.alloc)

