class GSL_Histogram2D(ctypes.Structure):
    pass

gsl.gsl_histogram2d_calloc_range.argtypes = [ctypes.c_size_t, ctypes.c_size_t, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
gsl.gsl_histogram2d_calloc_range.restype = ctypes.POINTER(GSL_Histogram2D)

def create_histogram2d(nx, ny, xrange, yrange):
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError('nx must be a positive integer')
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError('ny must be a positive integer')
    if not isinstance(xrange, list) or len(xrange) != nx + 1 or any(not isinstance(x, float) for x in xrange):
        raise ValueError('xrange must be a list of length nx+1 containing floats')
    if not isinstance(yrange, list) or len(yrange) != ny + 1 or any(not isinstance(y, float) for y in yrange):
        raise ValueError('yrange must be a list of length ny+1 containing floats')
    if not all(xrange[i] < xrange[i+1] for i in range(nx)) or not all(yrange[i] < yrange[i+1] for i in range(ny)):
        raise ValueError('xrange and yrange must be in increasing order')

    xrange_ptr = (ctypes.c_double * (nx + 1))(*xrange)
    yrange_ptr = (ctypes.c_double * (ny + 1))(*yrange)
    histogram = gsl.gsl_histogram2d_calloc_range(nx, ny, xrange_ptr, yrange_ptr)
    if not histogram:
        raise RuntimeError('Failed to allocate memory for histogram')
    return histogram

